const unit=v=>{const n=Math.hypot(...v)||1;return v.map(x=>x/n);};
const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
const dot=(a,b)=>a.reduce((s,x,i)=>s+x*b[i],0);
const cuts=[[[.82,.13,.55],.75],[[-.69,.49,.53],.87],[[.24,.95,-.18],.8],[[.18,-.98,.03],.78],[[.33,.16,-.93],.83]].map(([n,d])=>[unit(n),d]);
function rockPoint(direction){const [x,y,z]=direction;let r=1+.065*Math.sin(x*7+y*4-z*2)+.035*Math.sin(z*14-x*5+y*3)+.013*Math.cos(x*31+y*17+z*23);for(const [n,d] of cuts){const q=dot(direction,n);if(q>0)r=Math.min(r,d/q);}return [x*r*1.13,y*r*.96,z*r*.98];}
function rockNormal(d){const t=unit(cross(d,Math.abs(d[1])<.95?[0,1,0]:[1,0,0])),b=unit(cross(d,t)),e=.002;const axis=v=>{const a=rockPoint(unit(d.map((x,i)=>x+e*v[i]))),c=rockPoint(unit(d.map((x,i)=>x-e*v[i])));return a.map((x,i)=>x-c[i]);};let n=unit(cross(axis(t),axis(b)));if(dot(n,d)<0)n=n.map(x=>-x);return n;}
export function createOreGeometry(rings=64,slices=96){const vertices=[],normals=[],positions=[],surfaceNormals=[];for(let j=0;j<=rings;j++)for(let i=0;i<=slices;i++){const theta=j/rings*Math.PI,phi=i/slices*Math.PI*2,d=[Math.sin(theta)*Math.cos(phi),Math.cos(theta),Math.sin(theta)*Math.sin(phi)];vertices.push(rockPoint(d));normals.push(rockNormal(d));}const add=(a,b,c)=>{for(const k of [a,b,c]){positions.push(...vertices[k]);surfaceNormals.push(...normals[k]);}};for(let j=0;j<rings;j++)for(let i=0;i<slices;i++){const a=j*(slices+1)+i,b=a+1,c=a+slices+1,d=c+1;if(j>0)add(a,c,b);if(j<rings-1)add(b,c,d);}return {positions:new Float32Array(positions),normals:new Float32Array(surfaceNormals),triangles:positions.length/9};}
const hash=(x,y)=>{let h=Math.imul(x,374761393)^Math.imul(y,668265263);h=Math.imul(h^(h>>>13),1274126177);return ((h^(h>>>16))>>>0)/4294967295;};
const mix=(a,b,t)=>a+(b-a)*t;
function noise(x,y,period){const xx=x*period,yy=y*period,ix=Math.floor(xx),iy=Math.floor(yy),u=xx-ix,v=yy-iy,s=u*u*(3-2*u),t=v*v*(3-2*v);const h=(a,b)=>hash((a+period)%period,(b+period)%period);return mix(mix(h(ix,iy),h(ix+1,iy),s),mix(h(ix,iy+1),h(ix+1,iy+1),s),t);}
export function createOreTexture(size=512){const pixels=new Uint8Array(size*size*4);for(let y=0;y<size;y++)for(let x=0;x<size;x++){const u=x/size,v=y/size,coarse=noise(u,v,8),medium=noise(u,v,32),fine=noise(u,v,128),grain=noise(u,v,512),region=Math.max(0,Math.min(1,(coarse-.35)*2.5)),crack=Math.max(0,1-Math.abs(medium-.5)*60)*Math.max(0,(coarse-.38)*2),pore=Math.pow(Math.max(0,(.3-grain)/.3),2),fleck=grain>.9?(grain-.9)*1.7:0;const red=[137,74,48],dark=[70,64,58],base=red.map((c,i)=>mix(c,dark[i],region));const light=.74+.43*fine+.18*grain-.4*pore-.22*crack;const k=(y*size+x)*4;for(let i=0;i<3;i++)pixels[k+i]=Math.max(0,Math.min(255,base[i]*light+fleck*85));pixels[k+3]=Math.max(0,Math.min(255,(.38+.24*medium+.21*fine-.35*pore-.2*crack)*255));}return pixels;}
